package com.project.system.service;
import java.util.*;import java.math.*;import java.time.*;import java.nio.charset.*;import java.io.*;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.*;import org.springframework.web.multipart.MultipartFile;import com.fasterxml.jackson.databind.ObjectMapper;
@Service public class FinanceService {
 @Autowired private JdbcTemplate db;private final ObjectMapper json=new ObjectMapper();
 public static final String HEADER="merchantId,merchantSerialNo,campusOrderNo,tradeType,amount,status,occurredAt,originalSerialNo,platformVoucherNo";
 private LocalDate date(String s){try{return LocalDate.parse(s);}catch(Exception e){throw new IllegalArgumentException("请选择有效的起止日期");}}
 private void range(String start,String end){LocalDate a=date(start),b=date(end);if(b.isBefore(a)||java.time.temporal.ChronoUnit.DAYS.between(a,b)>30)throw new IllegalArgumentException("账期起止日期无效，单批最多31天");}
 private String snapshot(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
 private void audit(String batch,Long line,String action,long actor,String note){db.update("insert into campus_finance_audit(batch_id,line_id,action,actor_id,note) values(?,?,?,?,?)",batch,line,action,actor,note);}
 private String begin(String kind,Long merchant,String start,String end,String name,String hash,long actor){range(start,end);String id="DZ"+java.time.format.DateTimeFormatter.ofPattern("yyyyMMddHHmmss").withZone(ZoneId.of("Asia/Shanghai")).format(Instant.now())+UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase(Locale.ROOT);db.update("insert into campus_finance_batch(id,kind,merchant_id,start_date,end_date,source_name,source_hash,created_by) values(?,?,?,?,?,?,?,?)",id,kind,merchant,start,end,name,hash,actor);return id;}
 private void line(String batch,String category,String code,String key,String serial,String order,String type,BigDecimal merchant,BigDecimal platform,String ms,String ps,String reason,Object data){db.update("insert into campus_finance_line(batch_id,category,difference_code,business_key,merchant_serial,campus_order,trade_type,merchant_amount,platform_amount,merchant_status,platform_status,reason,snapshot,handling_status) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",batch,category,code,key,serial,order,type,merchant,platform,ms,ps,reason,snapshot(data),"MATCH".equals(code)?"AUTO":"PENDING");}
 private void finish(String batch,long actor){db.update("update campus_finance_batch set total_count=(select count(*) from campus_finance_line where batch_id=?),difference_count=(select count(*) from campus_finance_line where batch_id=? and difference_code<>'MATCH') where id=?",batch,batch,batch);audit(batch,null,"CREATE",actor,"保存对账快照；未修改钱包及交易记录");}
 public List<Map<String,Object>> merchants(){return db.queryForList("select m.id,m.name,c.public_id from campus_merchant m left join campus_api_credential c on c.merchant_id=m.id where m.id<>3 order by m.id");}
 public Map<String,Object> overview(String start,String end,Long merchant){range(start,end);Map<String,Object> r=new LinkedHashMap<>();r.put("period",db.queryForMap("select coalesce(sum(case when kind='RECHARGE' then amount else 0 end),0) recharge,coalesce(sum(case when kind='PAY' then amount else 0 end),0) consumption,coalesce(sum(case when kind='REFUND' then amount else 0 end),0) refunds,count(*) successful_records from campus_ledger where created_at>=? and created_at<date_add(?,interval 1 day)",start,end));r.put("balances",db.queryForMap("select coalesce(sum(balance),0) wallet_total,count(*) wallets from campus_wallet"));String scope=merchant==null?"":" and coalesce(l.merchant_id,o.merchant_id)=?";List<Object>a=new ArrayList<>(Arrays.asList(start,end));if(merchant!=null)a.add(merchant);r.put("merchant",db.queryForMap("select coalesce(sum(case when l.kind='PAY' then l.amount else 0 end),0) consumption,coalesce(sum(case when l.kind='REFUND' then l.amount else 0 end),0) refunds,coalesce(sum(case when l.kind='PAY' then l.amount else -l.amount end),0) net from campus_ledger l left join campus_ledger o on o.id=l.original_id where l.kind in ('PAY','REFUND') and coalesce(l.merchant_id,o.merchant_id)<>3 and l.created_at>=? and l.created_at<date_add(?,interval 1 day)"+scope,a.toArray()));r.put("pendingDifferences",db.queryForObject("select count(*) from campus_finance_line l join campus_finance_batch b on b.id=l.batch_id where b.status<>'ARCHIVED' and l.difference_code<>'MATCH' and l.handling_status<>'CONFIRMED'",Long.class));return r;}
 @Transactional(isolation=Isolation.REPEATABLE_READ) public String internal(String start,String end,long actor){String batch=begin("INTERNAL",null,start,end,null,null,actor);List<Map<String,Object>> rows=db.queryForList("select w.user_id,w.student_no,w.balance,coalesce(sum(case when l.kind='PAY' then -l.amount else l.amount end),0) ledger_balance from campus_wallet w left join campus_ledger l on l.user_id=w.user_id group by w.user_id,w.student_no,w.balance");if(rows.size()>20000)throw new IllegalArgumentException("钱包数量过多，需分批核对");for(Map<String,Object> x:rows){BigDecimal actual=(BigDecimal)x.get("balance"),ledger=(BigDecimal)x.get("ledger_balance");boolean match=actual.compareTo(ledger)==0;line(batch,"WALLET",match?"MATCH":"BALANCE_MISMATCH",String.valueOf(x.get("student_no")),null,null,null,actual,ledger,null,null,match?"当前钱包余额与全部成功资金流水一致":"钱包余额与流水汇总不一致；差额="+actual.subtract(ledger),x);}
 List<Map<String,Object>> orders=db.queryForList("select a.order_no,a.local_serial,a.request_id,a.trade_type,a.status,a.amount,a.ledger_id,l.transaction_no system_serial,coalesce(l.merchant_name_snapshot,m.name) merchant_name,e.introduction merchant_summary,a.description transaction_summary,a.occurred_at,a.location,l.id actual_ledger,l.kind ledger_kind,l.amount ledger_amount from campus_api_order a left join campus_ledger l on l.id=a.ledger_id left join campus_merchant m on m.id=a.merchant_id left join campus_merchant_extra e on e.merchant_id=m.id where a.created_at>=? and a.created_at<date_add(?,interval 1 day) limit 20001",start,end);if(orders.size()>20000)throw new IllegalArgumentException("订单数量过多，请缩短账期");for(Map<String,Object> x:orders){boolean success="SUCCESS".equals(x.get("status"));String code="MATCH",reason="订单状态与资金记录一致";if(success&&(x.get("actual_ledger")==null||!Objects.equals(x.get("trade_type"),x.get("ledger_kind"))||((BigDecimal)x.get("amount")).compareTo((BigDecimal)x.get("ledger_amount"))!=0)){code="ORDER_LEDGER_MISMATCH";reason="成功订单缺失资金记录，或金额、类型不一致";}else if(!success&&x.get("actual_ledger")!=null){code="ORDER_LEDGER_MISMATCH";reason="非成功订单存在资金记录";}else if("NEW".equals(x.get("status"))){code="PENDING";reason="订单尚无最终结果，请查询原订单";}line(batch,"API_ORDER",code,String.valueOf(x.get("order_no")),String.valueOf(x.get("local_serial")==null?x.get("request_id"):x.get("local_serial")),String.valueOf(x.get("order_no")),String.valueOf(x.get("trade_type")),(BigDecimal)x.get("amount"),(BigDecimal)x.get("ledger_amount"),String.valueOf(x.get("status")),x.get("actual_ledger")==null?"NONE":"SUCCESS",reason,x);}
 List<Map<String,Object>> charges=db.queryForList("select c.order_no,c.amount,c.status,c.ledger_id,l.transaction_no system_serial,c.created_at occurred_at,'校方充值入账' transaction_summary,l.amount ledger_amount,l.kind ledger_kind from campus_recharge_order c left join campus_ledger l on l.id=c.ledger_id where c.created_at>=? and c.created_at<date_add(?,interval 1 day) limit 20001",start,end);if(charges.size()>20000)throw new IllegalArgumentException("充值订单过多，请缩短账期");for(Map<String,Object> x:charges){boolean ok="SUCCESS".equals(x.get("status"))&&"RECHARGE".equals(x.get("ledger_kind"))&&x.get("ledger_amount")!=null&&((BigDecimal)x.get("amount")).compareTo((BigDecimal)x.get("ledger_amount"))==0;line(batch,"RECHARGE_ORDER",ok?"MATCH":"ORDER_LEDGER_MISMATCH",String.valueOf(x.get("order_no")),null,String.valueOf(x.get("order_no")),"RECHARGE",(BigDecimal)x.get("amount"),(BigDecimal)x.get("ledger_amount"),String.valueOf(x.get("status")),x.get("ledger_amount")==null?"NONE":"SUCCESS",ok?"充值订单与入账一致；外部收款真实性需另核凭证":"充值订单与入账不一致",x);}List<Map<String,Object>> unlinked=db.queryForList("select l.transaction_no system_serial,l.kind trade_type,l.amount,l.created_at occurred_at,coalesce(l.merchant_name_snapshot,m.name) merchant_name,e.introduction merchant_summary,'系统直接记账（无关联订单）' transaction_summary from campus_ledger l left join campus_merchant m on m.id=l.merchant_id left join campus_merchant_extra e on e.merchant_id=m.id where l.created_at>=? and l.created_at<date_add(?,interval 1 day) and not exists(select 1 from campus_api_order a where a.ledger_id=l.id) and not exists(select 1 from campus_recharge_order c where c.ledger_id=l.id) limit 20001",start,end);if(unlinked.size()>20000)throw new IllegalArgumentException("直接记账记录过多，请缩短账期");for(Map<String,Object> x:unlinked)line(batch,"DIRECT_LEDGER","MATCH",str(x.get("system_serial")),null,null,str(x.get("trade_type")),(BigDecimal)x.get("amount"),(BigDecimal)x.get("amount"),"SUCCESS","SUCCESS","系统直接记账，无关联订单；按资金流水单独列示",x);finish(batch,actor);return batch;}
 private List<List<String>> csv(byte[] bytes){String text;try{text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes)).toString();}catch(Exception e){throw new IllegalArgumentException("CSV须使用UTF-8编码");}if(text.startsWith("\ufeff"))text=text.substring(1);List<List<String>> rows=new ArrayList<>();List<String> row=new ArrayList<>();StringBuilder cell=new StringBuilder();boolean quoted=false,closed=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(quoted){if(c=='"'){if(i+1<text.length()&&text.charAt(i+1)=='"'){cell.append('"');i++;}else{quoted=false;closed=true;}}else cell.append(c);}else if(c==','||c=='\n'||c=='\r'){row.add(cell.toString());cell.setLength(0);closed=false;if(c!=','){if(c=='\r'&&i+1<text.length()&&text.charAt(i+1)=='\n')i++;if(row.size()>1||!row.get(0).isEmpty())rows.add(row);row=new ArrayList<>();}}else if(c=='"'&&cell.length()==0&&!closed)quoted=true;else{if(closed||c=='"')throw new IllegalArgumentException("CSV引号格式无效");cell.append(c);}if(cell.length()>2000||row.size()>12||rows.size()>5001)throw new IllegalArgumentException("账单字段过长、列数过多或超过5000条");}if(quoted)throw new IllegalArgumentException("CSV引号未闭合");if(cell.length()>0||!row.isEmpty()){row.add(cell.toString());rows.add(row);}return rows;}
 public List<List<String>> parse(MultipartFile file){if(file==null||file.isEmpty()||file.getSize()>5*1024*1024)throw new IllegalArgumentException("账单文件须为非空CSV或XLSX，最多5MB");try{String name=file.getOriginalFilename()==null?"":file.getOriginalFilename().toLowerCase(Locale.ROOT);List<List<String>> rows;if(name.endsWith(".csv"))rows=csv(file.getBytes());else if(name.endsWith(".xlsx")){rows=new ArrayList<>();try(org.apache.poi.ss.usermodel.Workbook workbook=org.apache.poi.ss.usermodel.WorkbookFactory.create(file.getInputStream())){if(workbook.getNumberOfSheets()!=1)throw new IllegalArgumentException("账单须仅有一个工作表");org.apache.poi.ss.usermodel.Sheet sheet=workbook.getSheetAt(0);if(sheet.getLastRowNum()>5000)throw new IllegalArgumentException("账单最多5000条");org.apache.poi.ss.usermodel.DataFormatter formatter=new org.apache.poi.ss.usermodel.DataFormatter(Locale.ROOT);for(org.apache.poi.ss.usermodel.Row r:sheet){List<String> values=new ArrayList<>();if(r.getLastCellNum()>9)throw new IllegalArgumentException("账单列数不正确");for(int i=0;i<9;i++){org.apache.poi.ss.usermodel.Cell cell=r.getCell(i);if(cell!=null&&cell.getCellTypeEnum()==org.apache.poi.ss.usermodel.CellType.FORMULA)throw new IllegalArgumentException("账单不能包含公式");String value=cell==null?"":formatter.formatCellValue(cell);if(value.length()>2000)throw new IllegalArgumentException("账单单元格过长");values.add(value);}rows.add(values);}}}else throw new IllegalArgumentException("仅支持CSV或XLSX账单");if(rows.isEmpty()||rows.size()>5001||!String.join(",",rows.get(0)).equals(HEADER))throw new IllegalArgumentException("表头不符合模板，或超过5000条");if(rows.size()<2)throw new IllegalArgumentException("账单没有明细");return rows;}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("无法读取账单，请检查文件格式及编码");}}
 private String str(Object v){return v==null?"":String.valueOf(v);}
 private String normalizedStatus(String status){return status.equals("NEW")?"PROCESSING":status;}
 @Transactional(isolation=Isolation.REPEATABLE_READ) public String importBill(long merchant,String start,String end,MultipartFile file,long actor){range(start,end);List<Map<String,Object>> creds=db.queryForList("select public_id from campus_api_credential where merchant_id=?",merchant);if(creds.size()!=1||merchant==3)throw new IllegalArgumentException("请选择已维护对接ID的经营商户");String uuid=str(creds.get(0).get("public_id"));List<List<String>> input=parse(file);List<Map<String,String>> parsed=new ArrayList<>();Map<String,Integer> duplicates=new HashMap<>();for(int i=1;i<input.size();i++){List<String> values=input.get(i);if(values.size()!=9)throw new IllegalArgumentException("第"+(i+1)+"行列数应为9");Map<String,String> row=new LinkedHashMap<>();String[] keys=HEADER.split(",");for(int k=0;k<keys.length;k++)row.put(keys[k],values.get(k).trim());if(!uuid.equals(row.get("merchantId")))throw new IllegalArgumentException("第"+(i+1)+"行商户UUID不匹配");if(row.get("campusOrderNo").length()>48||row.get("platformVoucherNo").length()>48||row.get("originalSerialNo").length()>64)throw new IllegalArgumentException("第"+(i+1)+"行订单或凭证编号过长");if(!row.get("merchantSerialNo").matches("[A-Za-z0-9_-]{8,64}"))throw new IllegalArgumentException("第"+(i+1)+"行商户流水号无效");if(!Arrays.asList("PAY","REFUND","RECHARGE").contains(row.get("tradeType")))throw new IllegalArgumentException("第"+(i+1)+"行类型无效");if(!row.get("amount").matches("[0-9]{1,10}(\\.[0-9]{1,2})?"))throw new IllegalArgumentException("第"+(i+1)+"行金额无效");if(new BigDecimal(row.get("amount")).signum()<=0)throw new IllegalArgumentException("金额须大于零");if(!Arrays.asList("SUCCESS","FAILED","PROCESSING").contains(row.get("status")))throw new IllegalArgumentException("账单状态须为SUCCESS、FAILED或PROCESSING");try{LocalDate day=OffsetDateTime.parse(row.get("occurredAt")).atZoneSameInstant(ZoneId.of("Asia/Shanghai")).toLocalDate();if(day.isBefore(date(start))||day.isAfter(date(end)))throw new IllegalArgumentException("第"+(i+1)+"行发生日期不在账期内");}catch(java.time.format.DateTimeParseException e){throw new IllegalArgumentException("第"+(i+1)+"行时间须为带时区ISO8601格式");}duplicates.put(row.get("merchantSerialNo"),duplicates.getOrDefault(row.get("merchantSerialNo"),0)+1);parsed.add(row);}
 List<Map<String,Object>> platform=db.queryForList("select a.order_no,a.request_id,a.local_serial,a.trade_type,a.amount,a.status,date_format(a.occurred_at,'%Y-%m-%d') business_date,a.created_at,a.location,a.description from campus_api_order a where a.merchant_id=? and a.occurred_at>=? and a.occurred_at<date_add(?,interval 1 day) limit 20001",merchant,start,end);if(platform.size()>20000)throw new IllegalArgumentException("平台交易超过20000条，请缩短账期");Map<String,Map<String,Object>> index=new LinkedHashMap<>();for(Map<String,Object> row:platform){String serial=str(row.get("local_serial"));if(serial.isEmpty())serial=str(row.get("request_id"));if(index.put(serial,row)!=null)throw new IllegalArgumentException("平台流水标识存在冲突，请缩短账期并人工核查");}List<Map<String,Object>> platformRefunds=db.queryForList("select l.transaction_no order_no,l.kind trade_type,l.amount,'SUCCESS' status,date_format(l.created_at,'%Y-%m-%d') business_date,coalesce(a.local_serial,a.request_id) original_serial from campus_ledger l join campus_ledger o on o.id=l.original_id left join campus_api_order a on a.ledger_id=o.id where l.kind='REFUND' and o.merchant_id=? and l.created_at>=? and l.created_at<date_add(?,interval 1 day) limit 20001",merchant,start,end);if(platformRefunds.size()>20000)throw new IllegalArgumentException("退款记录过多，请缩短账期");Set<String> usedRefunds=new HashSet<>();Set<String> used=new HashSet<>();String name=file.getOriginalFilename()==null?"账单":file.getOriginalFilename();if(name.length()>150)name=name.substring(name.length()-150);String hash;try{hash=ApiSecurity.hex(java.security.MessageDigest.getInstance("SHA-256").digest(file.getBytes()));}catch(Exception e){throw new IllegalStateException(e);}String batch=begin("MERCHANT",merchant,start,end,name,hash,actor);try{String sourceId=UUID.randomUUID().toString();db.update("insert into campus_finance_file(id,mime,content,actor_id) values(?,'application/octet-stream',?,?)",sourceId,file.getBytes(),actor);db.update("update campus_finance_batch set source_file_id=? where id=?",sourceId,batch);}catch(IOException e){throw new IllegalArgumentException("原账单保存失败");}
 for(Map<String,String> row:parsed){String serial=row.get("merchantSerialNo"),type=row.get("tradeType"),code="MATCH",reason="双方交易一致";Map<String,Object> found=index.get(serial);if(found!=null)used.add(serial);if(found==null&&!type.equals("REFUND")){List<Map<String,Object>> outside=db.queryForList("select order_no,request_id,local_serial,trade_type,amount,status,date_format(occurred_at,'%Y-%m-%d') business_date from campus_api_order where merchant_id=? and (request_id=? or local_serial=?) limit 2",merchant,serial,serial);if(outside.size()==1)found=outside.get(0);}
 if(found==null&&!type.equals("REFUND")&&!row.get("campusOrderNo").isEmpty()){List<Map<String,Object>> byOrder=db.queryForList("select order_no,request_id,local_serial,trade_type,amount,status,date_format(occurred_at,'%Y-%m-%d') business_date from campus_api_order where merchant_id=? and order_no=?",merchant,row.get("campusOrderNo"));if(byOrder.size()==1){found=byOrder.get(0);String actualSerial=str(found.get("local_serial"));if(actualSerial.isEmpty())actualSerial=str(found.get("request_id"));used.add(actualSerial);}}
 if(type.equals("REFUND")){String voucher=row.get("platformVoucherNo");List<Map<String,Object>> refunds=voucher.isEmpty()?Collections.emptyList():db.queryForList("select l.transaction_no order_no,l.kind trade_type,l.amount,'SUCCESS' status,date_format(l.created_at,'%Y-%m-%d') business_date,coalesce(a.local_serial,a.request_id) original_serial from campus_ledger l join campus_ledger o on o.id=l.original_id left join campus_api_order a on a.ledger_id=o.id where l.kind='REFUND' and o.merchant_id=? and l.transaction_no=?",merchant,voucher);if(refunds.size()==1){found=refunds.get(0);usedRefunds.add(voucher);}else{code="REFUND_VOUCHER_REQUIRED";reason="退款需提供可核对的内部退款资金凭证号，当前未接入商户退款API";}}
 if(duplicates.get(serial)>1){code="DUPLICATE";reason="商户账单出现重复流水号";}else if(code.equals("MATCH")&&found==null){code="MERCHANT_ONLY";reason="商户有记录，一卡通未找到对应交易";}else if(code.equals("MATCH")){List<String> differences=new ArrayList<>();if(!type.equals("REFUND")){String actualSerial=str(found.get("local_serial"));if(actualSerial.isEmpty())actualSerial=str(found.get("request_id"));if(!serial.equals(actualSerial))differences.add("商户流水号不一致");}if(type.equals("REFUND")&&!row.get("originalSerialNo").isEmpty()&&!str(found.get("original_serial")).isEmpty()&&!row.get("originalSerialNo").equals(str(found.get("original_serial"))))differences.add("退款关联的原商户流水号不一致");if(!type.equals(str(found.get("trade_type"))))differences.add("类型不一致");if(new BigDecimal(row.get("amount")).compareTo((BigDecimal)found.get("amount"))!=0)differences.add("金额不一致");if(!row.get("status").equals(normalizedStatus(str(found.get("status")))))differences.add("状态不一致");if(!row.get("campusOrderNo").isEmpty()&&!type.equals("REFUND")&&!row.get("campusOrderNo").equals(str(found.get("order_no"))))differences.add("一卡通订单号不一致");String billDay=OffsetDateTime.parse(row.get("occurredAt")).atZoneSameInstant(ZoneId.of("Asia/Shanghai")).toLocalDate().toString();if(!billDay.equals(str(found.get("business_date"))))differences.add("发生日期不一致，疑似跨日");if(!differences.isEmpty()){code="TRADE_MISMATCH";reason=String.join("；",differences);}else if(row.get("status").equals("PROCESSING")){code="PENDING";reason="交易尚无最终状态";}}
 Map<String,Object> snap=new LinkedHashMap<>();snap.put("merchant",row);snap.put("platform",found);line(batch,"TRADE",code,serial,serial,found==null?row.get("campusOrderNo"):str(found.get("order_no")),type,new BigDecimal(row.get("amount")),found==null?null:(BigDecimal)found.get("amount"),row.get("status"),found==null?"NONE":normalizedStatus(str(found.get("status"))),reason,snap);}
 for(Map.Entry<String,Map<String,Object>> entry:index.entrySet())if(!used.contains(entry.getKey())){Map<String,Object> x=entry.getValue();if("FAILED".equals(x.get("status")))continue;line(batch,"TRADE","NEW".equals(x.get("status"))?"PENDING":"PLATFORM_ONLY",entry.getKey(),entry.getKey(),str(x.get("order_no")),str(x.get("trade_type")),null,(BigDecimal)x.get("amount"),"NONE",normalizedStatus(str(x.get("status"))),"一卡通存在记录，商户账单未列出；请核对渠道及账期",x);}for(Map<String,Object> refund:platformRefunds)if(!usedRefunds.contains(str(refund.get("order_no"))))line(batch,"TRADE","PLATFORM_ONLY",str(refund.get("order_no")),null,str(refund.get("order_no")),"REFUND",null,(BigDecimal)refund.get("amount"),"NONE","SUCCESS","一卡通退款资金记录未出现在商户账单；请核对退款凭证",refund);finish(batch,actor);return batch;}
 public Map<String,Object> batches(String kind,Long merchant,int page){String where=" where 1=1";List<Object>a=new ArrayList<>();if(kind!=null&&!kind.isEmpty()){where+=" and b.kind=?";a.add(kind);}if(merchant!=null){where+=" and (b.merchant_id=? or b.kind='INTERNAL')";a.add(merchant);}Map<String,Object> r=new LinkedHashMap<>();r.put("total",db.queryForObject("select count(*) from campus_finance_batch b"+where,Long.class,a.toArray()));a.add(20);a.add((Math.max(1,Math.min(page,100000))-1)*20);r.put("rows",db.queryForList("select b.*,m.name merchant_name from campus_finance_batch b left join campus_merchant m on m.id=b.merchant_id"+where+" order by b.created_at desc,b.id desc limit ? offset ?",a.toArray()));return r;}
 public Map<String,Object> batch(String id){List<Map<String,Object>> r=db.queryForList("select b.*,m.name merchant_name from campus_finance_batch b left join campus_merchant m on m.id=b.merchant_id where b.id=?",id);if(r.isEmpty())throw new IllegalArgumentException("对账批次不存在");return r.get(0);}
 public Map<String,Object> lines(String batch,boolean differences,String handling,int page){return lines(batch,differences,handling,page,null);}
 public Map<String,Object> lines(String batch,boolean differences,String handling,int page,String scope){Map<String,Object> r=new LinkedHashMap<>();r.put("batch",batch(batch));String where=" where batch_id=?";List<Object>a=new ArrayList<>();a.add(batch);if("ORDERS".equals(scope))where+=" and category<>'WALLET'";else if("WALLET".equals(scope))where+=" and category='WALLET'";if(differences)where+=" and difference_code<>'MATCH'";if(handling!=null&&!handling.isEmpty()){where+=" and handling_status=?";a.add(handling);}r.put("total",db.queryForObject("select count(*) from campus_finance_line"+where,Long.class,a.toArray()));a.add(20);a.add((Math.max(1,Math.min(page,100000))-1)*20);r.put("rows",db.queryForList("select * from campus_finance_line"+where+" order by campus_order desc,id desc limit ? offset ?",a.toArray()));r.put("audit",db.queryForList("select * from campus_finance_audit where batch_id=? order by id desc limit 100",batch));return r;}
 private Map<String,Object> lockLine(long id){List<Map<String,Object>> rows=db.queryForList("select * from campus_finance_line where id=?",id);if(rows.isEmpty())throw new IllegalArgumentException("对账记录不存在");String batch=str(rows.get(0).get("batch_id"));db.queryForObject("select id from campus_finance_batch where id=? for update",String.class,batch);if("ARCHIVED".equals(batch(batch).get("status")))throw new IllegalArgumentException("批次已归档，不可更改");return db.queryForMap("select * from campus_finance_line where id=? for update",id);}
 private String note(String v){if(v==null||v.trim().isEmpty()||v.length()>1000)throw new IllegalArgumentException("请填写1至1000字的核实或复核说明");return v.trim();}
 @Transactional public void handle(long id,String note,String evidence,long actor){Map<String,Object>x=lockLine(id);if("MATCH".equals(x.get("difference_code"))||"CONFIRMED".equals(x.get("handling_status")))throw new IllegalArgumentException("该记录不需要处理或已复核确认");note=note(note);boolean hasNewEvidence=evidence!=null&&!evidence.isEmpty();if(!hasNewEvidence)evidence=(String)x.get("evidence_id");if(hasNewEvidence&&evidence!=null&&!evidence.isEmpty()&&db.queryForObject("select count(*) from campus_finance_file where id=? and actor_id=?",Integer.class,evidence,actor)!=1)throw new IllegalArgumentException("凭证不存在或不属于当前操作人");db.update("update campus_finance_line set handling_status='SUBMITTED',handled_by=?,handled_at=NOW(),handle_note=?,evidence_id=?,reviewed_by=null,reviewed_at=null,review_note=null where id=?",actor,note,evidence==null||evidence.isEmpty()?null:evidence,id);audit(str(x.get("batch_id")),id,"HANDLE",actor,note+"；凭证："+(evidence==null?"无":evidence));}
 @Transactional public void review(long id,boolean accept,String note,long actor){Map<String,Object>x=lockLine(id);if(!"SUBMITTED".equals(x.get("handling_status")))throw new IllegalArgumentException("差错尚未提交处理说明");if(((Number)x.get("handled_by")).longValue()==actor)throw new IllegalArgumentException("处理人与复核人不能为同一人");note=note(note);db.update("update campus_finance_line set handling_status=?,reviewed_by=?,reviewed_at=NOW(),review_note=? where id=?",accept?"CONFIRMED":"PENDING",actor,note,id);audit(str(x.get("batch_id")),id,accept?"CONFIRM":"RETURN",actor,note);}
 @Transactional public void archive(String id,long actor){db.queryForObject("select id from campus_finance_batch where id=? for update",String.class,id);if("ARCHIVED".equals(batch(id).get("status")))throw new IllegalArgumentException("批次已归档");if(db.queryForObject("select count(*) from campus_finance_line where batch_id=? and difference_code<>'MATCH' and handling_status<>'CONFIRMED'",Integer.class,id)>0)throw new IllegalArgumentException("仍有未处理或未复核差错，不能归档");db.update("update campus_finance_batch set status='ARCHIVED',archived_by=?,archived_at=NOW() where id=?",actor,id);audit(id,null,"ARCHIVE",actor,"归档对账快照；不代表完成商户结算或银行付款");}
 public String evidence(MultipartFile file,long actor){if(file==null||file.isEmpty()||file.getSize()>3*1024*1024)throw new IllegalArgumentException("凭证图片最多3MB");try{byte[] bytes=file.getBytes();javax.imageio.stream.ImageInputStream in=javax.imageio.ImageIO.createImageInputStream(new ByteArrayInputStream(bytes));try{Iterator<javax.imageio.ImageReader> it=javax.imageio.ImageIO.getImageReaders(in);if(!it.hasNext())throw new IllegalArgumentException("凭证须为有效PNG或JPEG图片");javax.imageio.ImageReader reader=it.next();try{reader.setInput(in);String f=reader.getFormatName();if(!f.equalsIgnoreCase("PNG")&&!f.equalsIgnoreCase("JPEG"))throw new IllegalArgumentException("仅支持PNG或JPEG凭证");if((long)reader.getWidth(0)*reader.getHeight(0)>12000000)throw new IllegalArgumentException("图片像素过大");ByteArrayOutputStream out=new ByteArrayOutputStream();javax.imageio.ImageIO.write(reader.read(0),f.equalsIgnoreCase("PNG")?"png":"jpg",out);if(out.size()>8*1024*1024)throw new IllegalArgumentException("图片解码后过大");String id=UUID.randomUUID().toString();db.update("insert into campus_finance_file(id,mime,content,actor_id) values(?,?,?,?)",id,f.equalsIgnoreCase("PNG")?"image/png":"image/jpeg",out.toByteArray(),actor);return id;}finally{reader.dispose();}}finally{in.close();}}catch(IOException e){throw new IllegalArgumentException("无法读取凭证图片");}}
 public Map<String,Object> file(String id){List<Map<String,Object>> r=db.queryForList("select mime,content from campus_finance_file where id=?",id);if(r.isEmpty())throw new IllegalArgumentException("凭证不存在");return r.get(0);}
 private String csvCell(Object value){String s=str(value);if(!s.trim().isEmpty()&&"=+@-".indexOf(s.trim().charAt(0))>=0)s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
 private String display(String value){String[][] pairs={{"DIRECT_LEDGER","系统直接记账"},{"WALLET","钱包余额"},{"API_ORDER","接口订单"},{"RECHARGE_ORDER","充值订单"},{"TRADE","商户交易"},{"MATCH","一致"},{"BALANCE_MISMATCH","余额不一致"},{"ORDER_LEDGER_MISMATCH","订单资金不一致"},{"MERCHANT_ONLY","商户单边"},{"PLATFORM_ONLY","一卡通单边"},{"TRADE_MISMATCH","交易信息不一致"},{"DUPLICATE","重复流水"},{"PENDING","待处理或待确定"},{"REFUND_VOUCHER_REQUIRED","退款凭证待核对"},{"AUTO","自动一致"},{"SUBMITTED","待复核"},{"CONFIRMED","已确认"},{"SUCCESS","成功"},{"FAILED","失败"},{"PROCESSING","处理中"},{"NONE","无记录"},{"PAY","消费"},{"REFUND","退款"},{"RECHARGE","充值"}};for(String[] p:pairs)if(p[0].equals(value))return p[1];return value;}
 public byte[] export(String id,long actor){batch(id);List<Map<String,Object>> rows=db.queryForList("select snapshot,category,difference_code,business_key,merchant_serial,campus_order,trade_type,merchant_amount,platform_amount,merchant_status,platform_status,reason,handling_status,handled_by,handle_note,reviewed_by,review_note from campus_finance_line where batch_id=? order by id",id);String[] keys={"system_serial","merchant_name","merchant_summary","transaction_summary","occurred_at","category","difference_code","business_key","merchant_serial","campus_order","trade_type","merchant_amount","platform_amount","merchant_status","platform_status","reason","handling_status","handled_by","handle_note","reviewed_by","review_note"};StringBuilder out=new StringBuilder("\ufeff系统资金流水号,商户名称,商户简介快照,交易摘要,发生时间,记录类别,差异类型,核对标识,商户流水号,一卡通订单或凭证号,交易类型,商户金额或钱包余额,平台金额或流水余额,商户状态,平台状态,说明,处理状态,处理人,处理说明,复核人,复核说明\r\n");for(Map<String,Object> row:rows){try{Map snap=json.readValue(str(row.get("snapshot")),Map.class);for(String field:Arrays.asList("system_serial","merchant_name","merchant_summary","transaction_summary","occurred_at"))row.put(field,snap.get(field));}catch(Exception ignored){}for(int k=0;k<keys.length;k++){if(k>0)out.append(',');Object value=row.get(keys[k]);if(Arrays.asList("category","difference_code","trade_type","merchant_status","platform_status","handling_status").contains(keys[k]))value=display(str(value));out.append(csvCell(value));}out.append("\r\n");}audit(id,null,"EXPORT",actor,"导出完整对账结果，共"+rows.size()+"条");return out.toString().getBytes(StandardCharsets.UTF_8);}
}
